-- v277 — forty-six things to wear (2026-10-17)
-- Run once in the Supabase SQL editor, after v276. Running it again is safe.
--
-- The owner, 2026-10-17: "ทำ 46 ชิ้นก่อน", of the list of things to wear both AIs made (nine outfits, eight hats, eight
-- glasses, ten things for the neck and eleven for the hair), everything had from the game. v276 gave the wardrobe a
-- table of its own (`town_dressed`), the bag's "wear" (`town_dress`) and the flower clip's chance; this gives the rest:
--
-- * Twenty are made at the uncle's workbench from what the lines already give (lib/town/wear-items' WEAR_CRAFTS: the
--   catalog's `workshop`), and four more are on his shelf (a monocle, square glasses, a necktie, a big ribbon: `goods`
--   and `shelf`). All twenty-four are things of the bag until worn once; the catalog's `dress` says what each is worn
--   into. A made thing's bench fee is what his family pays for it, so making and selling mints no coins.
-- * Six come with a sixth rank of a line, and nine more outfits' and hats' ranks are worked out on the page from the
--   lines' points, as the third ranks' are: nothing here.
-- * Sixteen are dropped: a chance at every count of a line's points that gives points, as the flower clip is, narrowed
--   by the deed, the thing, the Bangkok hour or the rain (lib/town/wear's Drop; the catalog's new row `wear_drops`, the
--   chances in ten-thousandths). `town.work_counted` rolls them all now; the flower clip is one of them, its chance still
--   the knob `wear_flower_in_ten_thousand`. The rarest are before dawn, mostly fishing and the forest (the owner's rule of
--   2026-10-15): the mushroom cap and the jewel beetle at 03–05, the sailor's stripes at 05–07. Each drop is rolled in a
--   block of its own, so a drop that fails never takes a deed's points with it.
-- * The bridge is built, so stones are laid no more: everybody who laid or handed on a stone (`town_deeds`) is given the
--   builder's outfit and medal now, and from now on they drop from helping somebody else's work, as the bridge was
--   built together (the owner: "อาจจะไม่มีสร้างสะพานอีกแล้ว ช่วยเปลี่ยนไปดรอปที่อื่น"): a rock somebody else struck
--   broken with one's swings, the bellows worked for somebody's piece at the smith, a tree somebody else fells braced.
--
-- What is mine, not answered: the chances, the uncle's prices, the recipes.

begin;
set local statement_timeout = '60s';
set local lock_timeout = '10s';
do $$ begin
 if to_regclass('public.town_dressed') is null or to_regprocedure('public.town_dress(integer)') is null then raise exception 'Run v276 before v277'; end if;
-- <guards:v277>
 if md5(replace(pg_get_functiondef('town.work_counted(uuid,jsonb,bigint)'::regprocedure),chr(13),'')) not in ('63b8d19332164e89787b11e92a82f4e6','f0cc664623807b8803e7e83171f9d9ca') then raise exception 'Definition changed: town.work_counted(uuid,jsonb,bigint); rebuild v277'; end if;
-- </guards:v277>
end $$;

-- The one writer of the lines' points, as since v149, with what a count that gives points may drop to wear (v276's flower
-- clip among them): the catalog's `wear_drops`, read once a call and only when a count gives points.
CREATE OR REPLACE FUNCTION town.work_counted(p_member uuid, p_done jsonb, p_at bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  c jsonb;
  who uuid;
  day_ integer := town.day_of(p_at);
  drops jsonb;
  d jsonb;
  hour_ double precision;
  wet boolean;
begin
  for c in select x from jsonb_array_elements(town.work_counts_of(p_done, p_member::text)) as t(x) loop
    begin
      who := coalesce((c->>'to')::uuid, p_member);
      update public.town_work w set kept = town.work_count(w.kept, c, day_) where w.member_id = who and w.line = c->>'line';
      if not found then
        insert into public.town_work (member_id, line, kept) values (who, c->>'line', town.work_count(town.work_new(), c, day_))
          on conflict (member_id, line) do update set kept = town.work_count(public.town_work.kept, c, day_);
      end if;
      -- v276, v277: what the count may drop to wear (lib/town/wear's dropsFor), each rule rolled on its own
      if coalesce((c->>'raw')::double precision, 0) > 0 then
        begin
          drops := coalesce(drops, town.cat('wear_drops'), '[]'::jsonb);
          for d in select x from jsonb_array_elements(drops) as r(x) where x->>'line' = c->>'line' loop
            continue when d ? 'what' and not ((d->'what') ? coalesce(p_done->>'what', ''));
            continue when d ? 'things' and not ((d->'things') ? coalesce(p_done->>'thing', ''));
            if d ? 'from' then
              hour_ := coalesce(hour_, town.hour_at(p_at));
              continue when not (case when (d->>'from')::double precision <= (d->>'to')::double precision
                then hour_ >= (d->>'from')::double precision and hour_ < (d->>'to')::double precision
                else hour_ >= (d->>'from')::double precision or hour_ < (d->>'to')::double precision end);
            end if;
            if coalesce((d->>'rain')::boolean, false) then
              wet := coalesce(wet, town.raining(p_at));
              continue when not wet;
            end if;
            continue when random() * 10000 >= coalesce(
              case when d ? 'knob' then (select k.value from public.town_knobs k where k.key = d->>'knob') end, (d->>'in')::double precision);
            insert into public.town_dressed (member_id, wearable, how) values (who, d->>'wear', 'drop') on conflict (member_id, wearable) do nothing;
          end loop;
        exception when others then null;
        end;
      end if;
    exception when others then null;
    end;
  end loop;
end;
$function$;

-- The bridge's builders: everybody whose hands a stone went through has the builder's outfit and medal.
insert into public.town_dressed (member_id, wearable, how)
select distinct d.member_id, w.wearable, 'drop'
  from public.town_deeds d
  cross join (values ('builder'), ('medal')) as w(wearable)
 where d.what in ('stone_lay', 'stone_hand') and d.member_id is not null
   and exists (select 1 from public.profiles p where p.id = d.member_id)
on conflict (member_id, wearable) do nothing;

-- <catalog:v277> written from lib/town/catalog.ts (npm test checks it; TOWN_WRITE=1 npx vitest run lib/town/catalog.test.ts writes it)
insert into public.town_catalog (key, data) values
  ('wear_drops', $town$[{"wear":"sailor","line":"fishing","in":100,"from":5,"to":7},{"wear":"lamplighter","line":"helpers","in":200,"what":["lamp_light","lamp_hand"]},{"wear":"builder","line":"helpers","in":200,"what":["hew","bellows","fell"]},{"wear":"raincoat","line":"forest","in":100,"what":["gather"],"rain":true},{"wear":"waiter","line":"kitchen","in":100,"what":["ladle"]},{"wear":"lampcap","line":"helpers","in":200,"what":["lamp_light","lamp_hand"]},{"wear":"mushroom","line":"forest","in":100,"what":["gather"],"from":3,"to":5},{"wear":"goggles","line":"fishing","in":50},{"wear":"crystalpendant","line":"mining","in":100,"what":["crystal","vein"]},{"wear":"medal","line":"helpers","in":200,"what":["hew","bellows","fell"]},{"wear":"beetle","line":"insects","in":100,"what":["net"],"from":3,"to":5},{"wear":"starpendant","line":"helpers","in":300,"what":["lamp_light","lamp_hand"],"from":19,"to":23},{"wear":"flower","line":"helpers","in":10,"knob":"wear_flower_in_ten_thousand"},{"wear":"leaf","line":"forest","in":50,"what":["gather"]},{"wear":"starclip","line":"insects","in":100,"what":["net"],"from":19,"to":23},{"wear":"butterfly","line":"insects","in":200,"what":["net"],"things":["butterflyWhite","monarch","morpho"]},{"wear":"featherpin","line":"felling","in":20,"what":["fell"]}]$town$::jsonb)
  on conflict (key) do nothing;
